        {
          "proposicao": "O processo eletrostático é apresentado como parte do processamento primário de petróleo para separar óleo, gás e água, e sua aplicação se relaciona à necessidade de enquadrar o óleo para transferência e a água para descarte.",
          "trechos": [
            "Efaf8e11877d0b18a:1397:2092"
          ],
          "condicoes": [
            "contexto de processamento primário de petróleo",
            "existência de emulsão água-em-óleo na produção"
          ],
          "limites": [
            "o trecho não descreve lógica de proteção elétrica, alarmes ou intertravamentos",
            "não informa parâmetros operacionais, limites de tensão, corrente ou temporização"
          ]
        },
        {
          "proposicao": "A formação e o tamanho das gotas de água na emulsão dependem de fatores como tensão interfacial, taxa de cisalhamento, agentes emulsificantes, presença de sólidos e propriedades do óleo e da água, o que afeta o comportamento do tratamento eletrostático.",
          "trechos": [
            "Efaf8e11877d0b18a:1397:2092",
            "Efaf8e11877d0b18a:2092:2486"
          ],
          "condicoes": [
            "emulsão água-em-óleo formada durante a produção",
            "escoamento com cisalhamento turbulento em dutos, bombas ou reservatório"
          ],
          "limites": [
            "o trecho não quantifica a influência de cada variável",
            "não estabelece critério de seleção de hardware elétrico"
          ]
        },
        {
          "proposicao": "A quebra de emulsão é descrita como um processo de coalescência de gotas que gera gotas maiores, favorecendo sua segregação posterior.",
          "trechos": [
            "Efaf8e11877d0b18a:2092:2486"
          ],
          "condicoes": [
            "existência de gotas dispersas em emulsão água-em-óleo"
          ],
          "limites": [
            "o trecho não detalha diagnóstico de campo instável",
            "não informa como alarmes, isoladores ou transformadores participam desse mecanismo"
          ]
        }
      ]
    },
    {
      "id": "E7057bfe235d47659",
