        {
          "proposicao": "Disjuntor é descrito como equipamento de manobra e proteção capaz de estabelecer, conduzir e interromper corrente nominal e também corrente de curto-circuito por tempo especificado.",
          "trechos": [
            "E7057bfe235d47659:0:700",
            "E7057bfe235d47659:700:1396"
          ],
          "condicoes": [
            "aplicação em sistema de potência",
            "equipamento em estado de fechamento, abertura e atuação de proteção"
          ],
          "limites": [
            "a fonte trata de disjuntores de forma geral, não especificamente do circuito de alta tensão de tratadores eletrostáticos em FPSOs",
            "não descreve integração com alarmes ou intertravamentos do processo de tratamento de óleo"
          ]
        },
        {
          "proposicao": "A constituição básica do disjuntor inclui meio isolante e extintor do arco, câmara de extinção, mecanismo de acionamento e componentes auxiliares de comando e controle.",
          "trechos": [
            "E7057bfe235d47659:700:1396",
            "E7057bfe235d47659:1396:2086"
          ],
          "condicoes": [
            "equipamento de alta tensão com função de interrupção"
          ],
          "limites": [
            "o trecho é conceitual e não identifica isoladores ou transformadores específicos de tratadores eletrostáticos",
            "não apresenta critérios de seleção para atmosferas inflamáveis em FPSO"
          ]
        },
        {
          "proposicao": "Para média e alta tensão, o acionamento do disjuntor pode depender de relés de proteção associados a transformadores para instrumentos.",
