          ]
        },
        {
          "proposicao": "No tratador convencional de baixa velocidade, a introdução da carga abaixo da região de eletrodos e próxima à interface água-óleo faz com que gotas maiores coalesçam antes, enquanto gotas menores seguem para região de campo mais intenso entre eletrodos.",
          "trechos": [
            "E8a9a1ee68398b3a6:700:1394"
          ],
          "condicoes": [
            "tratador convencional de baixa velocidade",
